/**
 * Arusha line-up cut-outs for the hero pop-in.
 *
 * Separate from ./artists.ts on purpose. `artists` drives the full-bleed carousel
 * artwork — square photography with a scrim, logos and copy baked into the slide.
 * A cut-out is a different asset: the person masked out of their background on
 * transparency, sized small, with nothing else in the file. One list cannot be
 * both without the cut-outs carrying scrims they must not have.
 *
 * Cut-outs are generated by `python3 scripts/build-assets.py talents` into
 * /public/talents as `<cutout>-<width>.avif|webp`. Both formats keep their alpha.
 * The sources are already framed waist-up at the camera, with clear margin on the
 * left, right and top so no arm is sliced by the canvas edge; only the waist runs
 * off the bottom, where the hero's bleed hides it. The build still owns the crop
 * (see TALENTS in scripts/build-assets.py) so a 3/4-length source supplied later
 * is cut there rather than in CSS, where it would be shown past its own pixels.
 *
 * ORDER IS THE ANIMATION ORDER. The hero pops these in one after another in the
 * order they appear here, so this list is the edit, not just the data.
 */
import type { Str } from '../i18n/strings'

/** Must match TALENT_WIDTHS in scripts/build-assets.py. */
export const TALENT_WIDTHS = [480, 720, 1080, 1500] as const

export type TalentRole = 'artist' | 'dj' | 'host'

export interface Talent {
  id: string
  /** Rendered uppercase by CSS; natural case here so screen readers say it as a name. */
  name: string
  role: TalentRole
  /**
   * File stem in /public/talents. Undefined means no cut-out exists yet — the
   * pop-in skips the entry rather than rendering a gap, so the line-up can be
   * filled in one talent at a time as artwork clears.
   */
  cutout?: string
  /**
   * Display scale relative to the shared line-up height, default 1.
   *
   * The hero normalises the cut-outs by height so they stand at one scale on one
   * baseline, which only reads correctly while the crops are framed alike. The
   * retoucher's originals were not — Juma held a bottle above his head, so the
   * raised arm rather than his head set the top of his frame and his face came
   * out about a quarter small — and each talent carried a correction here.
   *
   * The current set is shot waist-up to one brief, and measured at equal height
   * the three faces agree to within about 6% on sunglasses width, so none of them
   * sets a scale. The field is kept because the next cut-out supplied may well be
   * framed differently and this is where that is absorbed. Measure against the
   * sunglasses, which is the one feature all three share — hats and hair are not
   * comparable.
   */
  scale?: number
  /**
   * How the name breaks across the hero's stacked plates, default one plate
   * holding the whole name.
   *
   * Where a name breaks is an editorial decision, not a typographic accident:
   * the artwork sets JUMA over NATURE but keeps G NAKO whole on one plate, and
   * no rule derived from the name itself gets that right — splitting on spaces
   * would break G Nako, and never splitting would run Juma Nature out of the
   * column. So it is stated here, once, per talent.
   *
   * `name` stays the whole name and is what the image alt and any screen reader
   * announce; this is only how it is set.
   */
  nameLines?: string[]
  alt?: Str
}

/**
 * The Arusha line-up, in reveal order: cleared cut-outs first, then the talent
 * still waiting on artwork.
 *
 * [CONTENT-PENDING] Three cut-outs are cleared (transparent PNGs in
 * 00 - Assets/Talent Regen/Approved): Marioo, G Nako and Juma Nature. Ayra Starr
 * and Felo Le Tee have no photography at all; Joozey has press shots but no mask.
 * Their `cutout` stays undefined and the hero skips them rather than holding a
 * gap, so the line-up fills in one talent at a time as artwork clears.
 *
 * [DISCREPANCY] Juma Nature has a cleared cut-out but is NOT in the Arusha
 * line-up in campaign.ts (headliners: Marioo, G Nako, Ayra Starr, Felo Le Tee).
 * He is rendered here because the artwork was supplied for the hero, but the two
 * lists disagree and one of them is wrong — either he joins campaign.ts or he
 * comes out of here.
 */
export const talents: Talent[] = [
  { id: 'marioo', name: 'Marioo', role: 'artist', cutout: 'marioo' },
  { id: 'g-nako', name: 'G Nako', role: 'artist', cutout: 'g-nako' },
  { id: 'juma-nature', name: 'Juma Nature', role: 'artist', cutout: 'juma-nature', nameLines: ['Juma', 'Nature'] },
  { id: 'ayra-starr', name: 'Ayra Starr', role: 'artist' },
  { id: 'felo-le-tee', name: 'Felo Le Tee', role: 'artist' },
  { id: 'joozey', name: 'Joozey', role: 'dj' },
  { id: 'dommy', name: "D'Ommy", role: 'dj' },
]

/** Only the talent that can actually be drawn. The hero never renders a hole. */
export const revealable = () => talents.filter((x): x is Talent & { cutout: string } => !!x.cutout)
